class Solution:
    def minPathSum(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        row = [0] * n
        row[0] = grid[0][0]
        for j in range(1, n):
            row[j] = row[j - 1] + grid[0][j]
        for i in range(1, m):
            row[0] += grid[i][0]
            for j in range(1, n):
                row[j] = grid[i][j] + min(row[j], row[j - 1])   # above vs left
        return row[n - 1]

